command:
// Ajoute un ou plusieurs combattants sur la scène courante, depuis n'importe quel
// compendium d'acteurs disponible. Pensé pour ajuster une rencontre en cours de
// partie : liste déroulante groupée par compendium, import, placement sur les cases
// libres autour de la vue, et inscription au combat en cours.
(async () => {
    const t = (key, data) => data
        ? game.i18n.format("FQCARDENGINE." + key, data)
        : game.i18n.localize("FQCARDENGINE." + key);

    if (!game.user.isGM) return ui.notifications.warn(t("AddCombatantGMOnly"));

    const scene = canvas.scene;
    if (!scene) return ui.notifications.warn(t("AddCombatantNoScene"));

    // Facteur de puissance dnd5e : 0.125 / 0.25 / 0.5 s'affichent en fractions.
    const formatCr = (cr) => {
        const fractions = {0.125: "1/8", 0.25: "1/4", 0.5: "1/2"};
        return fractions[cr] ?? String(cr);
    };
    const escape = (value) => foundry.utils.escapeHTML(String(value));

    // Tout compendium d'acteurs, quel que soit le module qui le fournit : la liste
    // suit donc les compendiums réellement installés, sans id en dur.
    const actorPacks = game.packs.filter(pack => pack.documentName === "Actor");
    if (!actorPacks.length) return ui.notifications.error(t("AddCombatantNoActorPack"));

    const groups = [];
    for (const pack of actorPacks) {
        const index = await pack.getIndex({fields: ["system.details.cr"]});
        const entries = index.contents
            // Le SRD dnd5e expose des entrées « catégorie » (Aberration, Beast…) sans
            // facteur de puissance : ce ne sont pas des créatures invocables.
            .filter(entry => pack.metadata.id !== "dnd5e.monsters" || entry.system?.details?.cr !== undefined)
            .map(entry => {
                const cr = entry.system?.details?.cr;
                return {
                    uuid: entry.uuid ?? ("Compendium." + pack.metadata.id + ".Actor." + entry._id),
                    label: cr === undefined ? entry.name : t("AddCombatantEntryWithCr", {name: entry.name, cr: formatCr(cr)}),
                    sort: entry.name
                };
            })
            .sort((a, b) => a.sort.localeCompare(b.sort));
        if (entries.length) groups.push({label: pack.metadata.label ?? pack.metadata.id, entries});
    }
    groups.sort((a, b) => a.label.localeCompare(b.label));

    const total = groups.reduce((sum, group) => sum + group.entries.length, 0);
    if (!total) return ui.notifications.error(t("AddCombatantNoActor"));

    const options = groups.map(group =>
        "<optgroup label=\"" + escape(group.label) + "\">"
        + group.entries.map(entry => "<option value=\"" + escape(entry.uuid) + "\">" + escape(entry.label) + "</option>").join("")
        + "</optgroup>"
    ).join("");

    const form = await foundry.applications.api.DialogV2.prompt({
        window: {title: t("AddCombatantTitle")},
        content: [
            "<p>" + escape(t("AddCombatantSummary", {total, packs: groups.length})) + "</p>",
            "<div class=\"form-group\"><label>" + escape(t("AddCombatantFieldActor")) + "</label>",
            "<select name=\"uuid\" style=\"max-width: 22rem;\">" + options + "</select></div>",
            "<div class=\"form-group\"><label>" + escape(t("AddCombatantFieldCount")) + "</label>",
            "<input type=\"number\" name=\"count\" value=\"1\" min=\"1\" max=\"12\"></div>",
            "<div class=\"form-group\"><label>" + escape(t("AddCombatantFieldDisposition")) + "</label><select name=\"disposition\">",
            "<option value=\"-1\">" + escape(t("AddCombatantDispositionHostile")) + "</option>",
            "<option value=\"1\">" + escape(t("AddCombatantDispositionFriendly")) + "</option>",
            "<option value=\"0\">" + escape(t("AddCombatantDispositionNeutral")) + "</option>",
            "</select></div>",
            "<div class=\"form-group\"><label>" + escape(t("AddCombatantFieldCombat")) + "</label>",
            "<input type=\"checkbox\" name=\"combat\" checked></div>"
        ].join(""),
        ok: {
            label: t("AddCombatantValidate"),
            callback: (event, button) => ({
                uuid: button.form.elements.uuid.value,
                count: Math.max(1, Number(button.form.elements.count.value) || 1),
                disposition: Number(button.form.elements.disposition.value),
                combat: button.form.elements.combat.checked
            })
        },
        rejectClose: false
    });
    if (!form?.uuid) return;

    const source = await fromUuid(form.uuid);
    if (!source) return ui.notifications.error(t("AddCombatantActorNotFound", {uuid: form.uuid}));

    const actorData = source.toObject();
    delete actorData._id;
    const actor = await Actor.create(actorData);

    // Placement : on part de la case au centre de la vue courante et on cherche en
    // spirale la première zone libre assez grande pour la taille du token.
    const size = scene.grid.size;
    const {sceneX, sceneY} = scene.dimensions;
    const proto = actor.prototypeToken.toObject();
    const tokenCols = Math.max(1, Math.ceil(proto.width ?? 1));
    const tokenRows = Math.max(1, Math.ceil(proto.height ?? 1));

    const occupied = new Set();
    const occupy = (col, row, cols, rows) => {
        for (let dc = 0; dc < cols; dc++) {
            for (let dr = 0; dr < rows; dr++) occupied.add(col + dc + "," + (row + dr));
        }
    };
    for (const token of scene.tokens) {
        occupy(
            Math.round((token.x - sceneX) / size), Math.round((token.y - sceneY) / size),
            Math.max(1, Math.ceil(token.width)), Math.max(1, Math.ceil(token.height))
        );
    }

    const maxCol = Math.max(0, Math.floor(scene.width / size) - tokenCols);
    const maxRow = Math.max(0, Math.floor(scene.height / size) - tokenRows);
    const originCol = Math.min(maxCol, Math.max(0, Math.round((canvas.stage.pivot.x - sceneX) / size)));
    const originRow = Math.min(maxRow, Math.max(0, Math.round((canvas.stage.pivot.y - sceneY) / size)));

    const isFree = (col, row) => {
        for (let dc = 0; dc < tokenCols; dc++) {
            for (let dr = 0; dr < tokenRows; dr++) {
                if (occupied.has(col + dc + "," + (row + dr))) return false;
            }
        }
        return true;
    };
    const findFreeCell = () => {
        for (let radius = 0; radius <= 60; radius++) {
            for (let dc = -radius; dc <= radius; dc++) {
                for (let dr = -radius; dr <= radius; dr++) {
                    if (Math.max(Math.abs(dc), Math.abs(dr)) !== radius) continue;
                    const col = originCol + dc;
                    const row = originRow + dr;
                    if (col < 0 || row < 0 || col > maxCol || row > maxRow) continue;
                    if (isFree(col, row)) return {col, row};
                }
            }
        }
        return null;
    };

    const tokensData = [];
    for (let i = 0; i < form.count; i++) {
        const cell = findFreeCell();
        if (!cell) {
            ui.notifications.warn(t("AddCombatantNoFreeCell", {placed: i, count: form.count}));
            break;
        }
        occupy(cell.col, cell.row, tokenCols, tokenRows);
        const tokenData = {
            ...proto,
            actorId: actor.id,
            disposition: form.disposition,
            x: sceneX + (cell.col * size),
            y: sceneY + (cell.row * size)
        };
        delete tokenData._id;
        tokensData.push(tokenData);
    }
    if (!tokensData.length) return;

    const tokens = await scene.createEmbeddedDocuments("Token", tokensData);

    if (form.combat && game.combat) {
        const combatants = await game.combat.createEmbeddedDocuments(
            "Combatant",
            tokens.map(token => ({tokenId: token.id, actorId: actor.id, sceneId: scene.id}))
        );
        await game.combat.rollInitiative(combatants.map(combatant => combatant.id));
    }

    ui.notifications.info(t("AddCombatantDone", {count: tokens.length, actor: actor.name}));
})();
